// O app ja abriu o cadastro antes de mandar apagar, entao ele conhece os
// enderecos e contatos: nao precisamos procurar de novo aqui.
const b = $('Recupera pedido').first().json.body || {};
const limpa = (v) => String(v || '').split(',').map((x) => x.trim())
  .filter((x) => /^rec[A-Za-z0-9]{14}$/.test(x));

const entidadeId = limpa(b.id)[0];
if (!entidadeId) throw new Error('Pedido sem o codigo do cadastro.');

const lidos = $('Busca contatos do cadastro').all().map((i) => i.json);
if (lidos.some((j) => j && j.error)) throw new Error('Nao consegui conferir os contatos antes de tirar.');
const vinculosAtuais = new Map(lidos.filter((j) => j && j.id).map((j) => [j.id, (j.fields && j.fields.Entidades_Vinculadas) || []]));
const separaContatos = (idsContatos) => {
  const soDeste = [], deOutros = [];
  for (const id of idsContatos) {
    const vinculos = vinculosAtuais.get(id);
    if (vinculos && vinculos.some((e) => e !== entidadeId)) {
      deOutros.push({ id, fields: { Entidades_Vinculadas: vinculos.filter((e) => e !== entidadeId) } });
    } else soDeste.push(id);
  }
  return { soDeste, deOutros };
};

const BASE = 'http://127.0.0.1:5690/v0/app6PyYmtFduIMp7B/';
const TABELAS = { locais: 'tblffVczCf1VeNxs7', contatos: 'tblXXOEOCwQnC2qFX', entidades: 'tbl5Joji6gAir3mNh' };

// O Airtable apaga no maximo 10 por chamada.
const emLotes = (ids) => {
  const lotes = [];
  for (let i = 0; i < ids.length; i += 10) lotes.push(ids.slice(i, i + 10));
  return lotes;
};
const monta = (tabela, ids) => emLotes(ids).map((lote) => ({
  json: { url: BASE + tabela + '?' + lote.map((id) => 'records[]=' + id).join('&') },
}));
// Contato que também é de outra empresa não é apagado: só perde o vínculo com este cliente.
const tirar = separaContatos(limpa(b.contatosIds));
const desliga = emLotes(tirar.deOutros).map((lote) => ({
  json: { metodo: 'PATCH', url: BASE + TABELAS.contatos, corpo: { typecast: true, records: lote } },
}));

// Os ligados saem primeiro; o cadastro por ultimo, para nao sobrar
// endereco apontando para um cliente que ja deixou de existir.
return [
  ...monta(TABELAS.locais, limpa(b.locaisIds)),
  ...desliga,
  ...monta(TABELAS.contatos, tirar.soDeste),
  ...monta(TABELAS.entidades, [entidadeId]),
];

